UPDATE dbo.Story
Title = #{title}, Description = #{description, jdbcType=NVARCHAR}, CoverUrl = #{coverUrl, jdbcType=VARCHAR}, AgeRating = #{ageRating}, CompletionStatus = #{completionStatus}, UpdatedAt = SYSUTCDATETIME()
WHERE StoryId = #{storyId} AND AuthorId = #{authorId} AND IsDeleted = 0 AND UpdatedAt = #{version}
